import{_ as t,o as r,c as a,a2 as n}from"./chunks/framework.BWuWLRhz.js";const s=JSON.parse('{"title":"wikimem ADR 索引","description":"","frontmatter":{},"headers":[],"relativePath":"adr/README.md","filePath":"adr/README.md","lastUpdated":1785424162000}'),d={name:"adr/README.md"};function l(i,e,o,m,h,g){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="wikimem-adr-索引" tabindex="-1">wikimem ADR 索引 <a class="header-anchor" href="#wikimem-adr-索引" aria-label="Permalink to &quot;wikimem ADR 索引&quot;">​</a></h1><p>wikimem 的架构决策记录（Architecture Decision Records）。</p><p>创始设计不在本目录：存储层（categories + wiki-links + journal）、检索管线（BM25 + 可选 embedding 融合）以及三条硬约束，来源于宿主项目的 <a href="https://github.com/XnneHangLab/XnneHangLab/blob/dev/docs/adr/0001-llm-mode-memory.md" target="_blank" rel="noreferrer">XnneHangLab ADR-0001</a>（记忆管线）与 <a href="https://github.com/XnneHangLab/XnneHangLab/blob/dev/docs/adr/0002-memu-design-not-dependency.md" target="_blank" rel="noreferrer">XnneHangLab ADR-0002</a>（memU——借鉴设计而非引入依赖）。wikimem 独立成库后，<strong>框架自身的决策记录在这里</strong>；宿主侧的策略决策（意图识别、memorize 策略、情绪、前端）仍记录在 XnneHangLab 的 <code>docs/adr</code>。两边编号各自独立，跨仓引用时注明仓库名。</p><h2 id="继承的硬约束-来自-xnnehanglab-adr-0001" tabindex="-1">继承的硬约束（来自 XnneHangLab ADR-0001） <a class="header-anchor" href="#继承的硬约束-来自-xnnehanglab-adr-0001" aria-label="Permalink to &quot;继承的硬约束（来自 XnneHangLab ADR-0001）&quot;">​</a></h2><ol><li><strong>零基础设施</strong>：没有 embedding 模型、向量库、图数据库时系统必须可用——BM25 兜底，embedding 只是可选增强。</li><li><strong>不为记忆等待 LLM</strong>：retrieve 路径 0 次 LLM 调用；memorize 至多 1 次 LLM 调用、异步、由宿主发起。框架本体零 LLM。</li><li><strong>磁盘上不允许有不可读的真相</strong>：markdown 文件是唯一事实源；一切索引/向量都是可删除、可重建的派生缓存。</li></ol><h2 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引&quot;">​</a></h2><p><strong>状态</strong>记录的是<strong>架构决策</strong>本身：设计 PR 评审合并，即代表该决策在架构层面被采纳（Accepted）。<strong>实施</strong>记录的是<strong>代码</strong>的落地程度。</p><p>两者独立，因此 <strong>暂缓（0004 的 serve）或分期开发（0006 的 ④）属于实施进度，不改变决策已经生效这件事</strong>。想知道某条决策还欠着什么，看「实施」列，不要看「状态」列。</p><table tabindex="0"><thead><tr><th>编号</th><th>标题</th><th>状态</th><th>实施</th></tr></thead><tbody><tr><td><a href="./0001-diary-store.html">0001</a></td><td>日记原语 — 事件流与状态层分离</td><td>Accepted</td><td>✅ <a href="https://github.com/XnneHangLab/wikimem/pull/16" target="_blank" rel="noreferrer">#16</a> <a href="https://github.com/XnneHangLab/wikimem/pull/17" target="_blank" rel="noreferrer">#17</a> <a href="https://github.com/XnneHangLab/wikimem/pull/19" target="_blank" rel="noreferrer">#19</a></td></tr><tr><td><a href="./0002-time-range-retrieval.html">0002</a></td><td>时间检索 — time_range 门控 + 正则快通道，不做第三路融合</td><td>Accepted</td><td>⚠️ 门控已落地 <a href="https://github.com/XnneHangLab/wikimem/pull/26" target="_blank" rel="noreferrer">#26</a> <a href="https://github.com/XnneHangLab/wikimem/pull/27" target="_blank" rel="noreferrer">#27</a> <a href="https://github.com/XnneHangLab/wikimem/pull/31" target="_blank" rel="noreferrer">#31</a>；§6 recency 衰减项未做</td></tr><tr><td><a href="./0003-vectors-cache-metadata.html">0003</a></td><td>向量缓存记录 model/dim — 失配警告并降级，而非报错重建</td><td>Accepted</td><td>✅ <a href="https://github.com/XnneHangLab/wikimem/pull/33" target="_blank" rel="noreferrer">#33</a></td></tr><tr><td><a href="./0004-api-contract-thin-shells.html">0004</a></td><td>接口契约 — Python API 是契约，CLI 与 serve 都是薄壳</td><td>Accepted</td><td>⚠️ CLI 已落地 <a href="https://github.com/XnneHangLab/wikimem/pull/12" target="_blank" rel="noreferrer">#12</a>；serve 暂缓</td></tr><tr><td><a href="./0005-memorize-injected-llm.html">0005</a></td><td>memorize — 注入式 LLM，两种宿主驱动写入（后台抽取 / Agent 工具）</td><td>Accepted</td><td>⚠️ 模式 A 已落地 <a href="https://github.com/XnneHangLab/wikimem/pull/24" target="_blank" rel="noreferrer">#24</a>；模式 B 未做</td></tr><tr><td><a href="./0006-recallfile-read-unified-write-split.html">0006</a></td><td>RecallFile / RecallItem — 读侧统一，写侧分立（含命名收敛、日记向量化、jsonl 不迁 sqlite）</td><td>Accepted</td><td>⚠️ ①②③ 已落地 <a href="https://github.com/XnneHangLab/wikimem/pull/29" target="_blank" rel="noreferrer">#29</a> <a href="https://github.com/XnneHangLab/wikimem/pull/30" target="_blank" rel="noreferrer">#30</a> <a href="https://github.com/XnneHangLab/wikimem/pull/32" target="_blank" rel="noreferrer">#32</a> <a href="https://github.com/XnneHangLab/wikimem/pull/34" target="_blank" rel="noreferrer">#34</a>；④ 待 bench</td></tr></tbody></table><blockquote><p>0001 / 0002 的完整设计讨论（三种时间融合方案的对比分析）见博客《RRF vs Hybrid Search》（nyakku.moe，撰写中）。</p></blockquote>',10)])])}const c=t(d,[["render",l]]);export{s as __pageData,c as default};
